def _items(state: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    rows = state.get(key)
    return [dict(row) for row in rows if isinstance(row, Mapping)] if isinstance(rows, list) else []


def _number(value: Any) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return float("nan")


def _summary(row: Mapping[str, Any]) -> dict[str, Any]:
    allowed = {"seq", "type", "transactionId", "disputeId", "caseNumber", "reason", "paymentId", "billerId", "fromAccountId", "amount", "scheduledDate", "recipientId", "recipientName", "bank", "mask", "transferId", "memo", "q", "total"}
    return {key: row.get(key) for key in allowed if key in row}


class OpenBankTask01551454Evaluator(BaseEvaluator):
    EVALUATOR_ID = EVALUATOR_ID
    RULESET_SPEC = RULESET_SPEC
    RULESET_SHA256 = RULESET_SHA256
    CHECKPOINT_SPECS = CHECKPOINT_SPECS

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return self._error("controller.run_python_script is required")
        port = int(dict(context.get("params") or {}).get("port", 4340))
        try:
            state = self._fetch_state(controller, port)
            observation = controller.observe(include_ui_tree=True, include_screenshot_data=False)
            return self.evaluate_state(state, foreground_app=str(observation.foreground_app or ""), foreground_window=str(observation.foreground_window or ""))
        except Exception as exc:
            return self._error(f"OpenBank evaluation error: {type(exc).__name__}: {exc}")

    @classmethod
    def evaluate_state(cls, state: Mapping[str, Any], *, foreground_app: str = "openbank.exe", foreground_window: str = "OpenBank") -> EvalResult:
        checks: list[dict[str, Any]] = []
        all_events = _items(state, "events")
        logins = [row for row in all_events if row.get("type") == "session_login_success"]
        start_seq = int((logins[-1] if logins else {}).get("seq", -1))
        events = [row for row in all_events if int(row.get("seq", -1)) > start_seq]
        ordered_events: list[Mapping[str, Any] | None] = []

        recipients = _items(state, "recipients")
        recipient_by_name: dict[str, Mapping[str, Any]] = {}
        for index, expected in enumerate(RULESET_SPEC["recipients"]):
            matches = [row for row in recipients if all(row.get(key) == value for key, value in expected.items())]
            target = matches[0] if len(matches) == 1 else None
            event_matches = [row for row in events if target and row.get("type") == "transfer_recipient_added" and row.get("recipientId") == target.get("id") and row.get("recipientName") == expected["name"] and row.get("bank") == expected["bank"] and row.get("mask") == expected["mask"]]
            event = event_matches[0] if len(event_matches) == 1 else None
            checks.append(cls._check(CHECKPOINT_SPECS[index], target is not None and event is not None, {"object_count": len(matches), "object": target or matches, "event": _summary(event or {})}))
            if target:
                recipient_by_name[expected["name"]] = target
            ordered_events.append(event)

        transfers = _items(state, "transfers")
        for offset, expected in enumerate(RULESET_SPEC["transfers"], start=3):
            recipient = recipient_by_name.get(expected["recipientName"])
            matches = [row for row in transfers if recipient and row.get("recipientId") == recipient.get("id") and all((_number(row.get(key)) == value if key == "amount" else row.get(key) == value) for key, value in expected.items())]
            target = matches[0] if len(matches) == 1 else None
            event_matches = [row for row in events if target and row.get("type") == "transfer_scheduled" and row.get("transferId") == target.get("id") and row.get("recipientId") == recipient.get("id") and row.get("fromAccountId") == expected["fromAccountId"] and _number(row.get("amount")) == expected["amount"] and row.get("scheduledDate") == expected["scheduledDate"] and row.get("memo") == expected["memo"]]
            event = event_matches[0] if len(event_matches) == 1 else None
            checks.append(cls._check(CHECKPOINT_SPECS[offset], target is not None and event is not None, {"object_count": len(matches), "object": target or matches, "event": _summary(event or {})}))
            ordered_events.append(event)

        payments = _items(state, "billPayments")
        for offset, expected in enumerate(RULESET_SPEC["bill_payments"], start=6):
            matches = [row for row in payments if row.get("billerId") == expected["billerId"] and row.get("fromAccountId") == expected["fromAccountId"] and _number(row.get("amount")) == expected["amount"] and row.get("scheduledDate") == expected["scheduledDate"] and row.get("memo") == expected["memo"] and row.get("status") == "Scheduled"]
            target = matches[0] if len(matches) == 1 else None
            event_matches = [row for row in events if target and row.get("type") == "bill_payment_scheduled" and row.get("paymentId") == target.get("id") and row.get("billerId") == expected["billerId"] and row.get("fromAccountId") == expected["fromAccountId"] and _number(row.get("amount")) == expected["amount"] and row.get("scheduledDate") == expected["scheduledDate"]]
            event = event_matches[0] if len(event_matches) == 1 else None
            checks.append(cls._check(CHECKPOINT_SPECS[offset], target is not None and event is not None, {"object_count": len(matches), "object": target or matches, "event": _summary(event or {})}))
            ordered_events.append(event)

        disputes = _items(state, "disputes")
        for offset, expected in enumerate(RULESET_SPEC["disputes"], start=8):
            matches = [row for row in disputes if row.get("merchant") == expected["merchant"] and row.get("reason") == expected["reason"] and row.get("contactedMerchant") is True and row.get("details") == expected["details"] and row.get("status") == "Submitted"]
            target = matches[0] if len(matches) == 1 else None
            search_events = [row for row in events if row.get("type") == "transactions_viewed" and row.get("q") == expected["query"] and int(row.get("total", 0)) > 0]
            detail_events = [row for row in events if target and row.get("type") == "transaction_details_viewed" and row.get("transactionId") == target.get("transactionId")]
            submit_events = [row for row in events if target and row.get("type") == "transaction_dispute_submitted" and row.get("disputeId") == target.get("id") and row.get("transactionId") == target.get("transactionId") and row.get("reason") == expected["reason"]]
            search = search_events[-1] if search_events else None
            detail = next((row for row in detail_events if search and int(row.get("seq", -1)) > int(search.get("seq", -1))), None)
            submit = next((row for row in submit_events if detail and int(row.get("seq", -1)) > int(detail.get("seq", -1))), None)
            passed = len(matches) == 1 and search is not None and detail is not None and submit is not None
            checks.append(cls._check(CHECKPOINT_SPECS[offset], passed, {"object_count": len(matches), "search": _summary(search or {}), "detail": _summary(detail or {}), "submit": _summary(submit or {}), "object": target or matches}))
            ordered_events.append(submit)

        order_actual = [_summary(row or {}) for row in ordered_events]
        order_passed = all(ordered_events) and all(int(left.get("seq", -1)) < int(right.get("seq", -1)) for left, right in zip(ordered_events, ordered_events[1:]))
        checks.append(cls._check(CHECKPOINT_SPECS[10], bool(order_passed), order_actual))
        foreground_passed = foreground_app.casefold() in {"openbank", "openbank.exe"} and "openbank" in foreground_window.casefold()
        checks.append({"name": "foreground_openbank", "value_contract_id": "openbank.task01.foreground", "instruction_steps": list(range(1, 79)), "match_mode": "FINAL_UI_APP_EXACT", "expected": {"app": "openbank.exe", "window": "OpenBank"}, "actual": {"app": foreground_app, "window": foreground_window}, "passed": foreground_passed})

        covered = {step for spec in CHECKPOINT_SPECS for step in spec["steps"]}
        if covered != set(range(1, 79)):
            return cls._error("checkpoint map does not cover exactly steps 1..78", checks)
        failed = [row["name"] for row in checks if not row["passed"]]
        metadata = {"task_id": TASK_ID, "read_only": True, "source_state_mode": "human_completed_eval_only", "business_state_mutations": [], "evaluator_id": EVALUATOR_ID, "ruleset_sha256": RULESET_SHA256, "ruleset_spec": RULESET_SPEC, "step_groups": STEP_GROUPS, "checkpoint_specs": CHECKPOINT_SPECS, "covered_instruction_steps": list(range(1, 79)), "checks": checks, "failed_checks": failed}
        return EvalResult(status=EvalStatus.FAIL if failed else EvalStatus.PASS, message=("OpenBank task01 evaluation failed: " + ", ".join(failed)) if failed else "All OpenBank task01 checks passed", metadata=metadata)

    @staticmethod
    def _check(spec: Mapping[str, Any], passed: bool, actual: Any) -> dict[str, Any]:
        return {"name": str(spec["value_contract_id"]), "value_contract_id": spec["value_contract_id"], "instruction_steps": list(spec["steps"]), "match_mode": spec["match_mode"], "expected": spec["expected"], "actual": actual, "passed": bool(passed)}

    @classmethod
    def _error(cls, message: str, checks: list[dict[str, Any]] | None = None) -> EvalResult:
        return EvalResult(status=EvalStatus.ERROR, message=message, metadata={"task_id": TASK_ID, "read_only": True, "evaluator_id": EVALUATOR_ID, "ruleset_sha256": RULESET_SHA256, "ruleset_spec": RULESET_SPEC, "step_groups": STEP_GROUPS, "checkpoint_specs": CHECKPOINT_SPECS, "checks": checks or [], "failed_checks": [row["name"] for row in checks or [] if not row.get("passed")]})

    @staticmethod
    def _fetch_state(controller: Any, port: int) -> Mapping[str, Any]:
        code = """import urllib.request\nwith urllib.request.urlopen(%r, timeout=8) as response:\n    print(response.read().decode('utf-8'))\n""" % f"http://127.0.0.1:{port}/api/evaluation"
        result = controller.run_python_script(code, timeout=12)
        if int(result.get("returncode", -1)) != 0:
            raise RuntimeError(str(result.get("stderr") or result.get("output") or "API request failed"))
        payload = json.loads(str(result.get("stdout") or result.get("output") or ""))
        if not isinstance(payload, Mapping):
            raise TypeError("OpenBank evaluation payload must be an object")
        return payload
